-- This machine's hardware facts. Generated by chezmoi from
-- .chezmoidata/machines.toml; see machine.lua.tmpl. Branch on the capability
-- flags below, never on hostname, so a new machine is a data entry.
local machine = require("machine")

--- Monitor to pin a window or workspace to, or nil on a machine without a real
--- primary+secondary layout, where naming an output is meaningless.
--- @param output string
--- @return string|nil
local function pin(output)
    return machine.multihead and output or nil
end

------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/

for _, m in ipairs(machine.monitors) do
    hl.monitor({ output = m.output, mode = m.mode, position = m.position, scale = m.scale, transform = m.transform })
end

