---- AUTOSTART ----
-------------------

-- Autostart keys that name a program local above. Looking the local up here
-- keeps it the single definition of the command, rather than repeating the
-- string in machines.toml.
local autostartLocals = {
    lockscreen = lockscreen,
}

hl.on("hyprland.start", function()
    for _, key in ipairs(machine.autostart) do
        hl.exec_cmd(autostartLocals[key] or machine.commands[key])
    end
end)

